using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Exports an invoice as a PDF byte stream.</summary>
public sealed class PdfExporter
{
    private readonly IPdfRenderer _renderer;

    public PdfExporter(IPdfRenderer renderer) => _renderer = renderer;

    public byte[] Export(Invoice invoice)
    {
        ArgumentNullException.ThrowIfNull(invoice);
        var lines = invoice.Lines
            .Select(line => $"{line.Description}: {line.NetAmount}")
            .ToList();
        return _renderer.ToPdf($"Invoice {invoice.Number}", lines);
    }
}

public interface IPdfRenderer
{
    byte[] ToPdf(string title, IEnumerable<string> lines);
}

public sealed class SupportedPdfRenderer : IPdfRenderer
{
    public byte[] ToPdf(string title, IEnumerable<string> lines)
    {
        return RenderApiV2.ToPdf(title, lines);
    }
}
